// After `astro build`: every page's sidebar has no empty group, and every built page is in the sidebar. On
// 2026-11-19 every autogenerated group rendered as `<details><summary>…</summary><ul></ul></details>` (the
// autogenerate directories matched no entry, astro.config.mjs): clicking a group only folded an empty list, and
// no page could be reached from the sidebar. The build succeeded anyway, so this fails it instead.
//
//   node scripts/check-sidebar.mjs [dist]     default: apps/docs/dist

import { readFileSync, readdirSync, statSync } from 'node:fs';
import { join, relative, sep } from 'node:path';
import { fileURLToPath } from 'node:url';

const BASE = '/docs/';
const dist = process.argv[2] ?? fileURLToPath(new URL('../dist', import.meta.url));

/** Every index.html under `dir`. */
function pages(dir) {
  const out = [];
  for (const n of readdirSync(dir)) {
    const p = join(dir, n);
    if (statSync(p).isDirectory()) out.push(...pages(p));
    else if (n === 'index.html') out.push(p);
  }
  return out;
}

/** The sidebar's markup: Starlight's `<ul class="top-level">` up to the end of its persist element. */
function sidebarOf(html) {
  const at = html.indexOf('<sl-sidebar-state-persist');
  if (at < 0) return null;
  const end = html.indexOf('</sl-sidebar-state-persist>', at);
  return html.slice(at, end < 0 ? undefined : end).replace(/ data-astro-cid-\w+(="[^"]*")?/g, '');
}

/** Each group's label whose list holds no link. */
function emptyGroups(sidebar) {
  const out = [];
  const group = /<summary>([\s\S]*?)<\/summary>(?:\s*<sl-sidebar-restore[^>]*><\/sl-sidebar-restore>)?\s*<ul[^>]*>\s*<\/ul>/g;
  for (const m of sidebar.matchAll(group)) out.push(m[1].replace(/<[^>]+>/g, '').trim());
  return out;
}

const problems = [];
const files = pages(dist);
const linked = new Set();
for (const f of files) {
  const rel = relative(dist, f).split(sep).join('/');
  const sidebar = sidebarOf(readFileSync(f, 'utf8'));
  // the splash home page has no sidebar
  if (sidebar === null) continue;
  for (const g of emptyGroups(sidebar)) problems.push(`${rel}: the sidebar group "${g}" is empty`);
  for (const m of sidebar.matchAll(/<a href="([^"]+)"/g)) linked.add(m[1]);
}
// every page with a sidebar is reachable from it (the home page and 404 aren't pages of a group)
for (const f of files) {
  const rel = relative(dist, f).split(sep).join('/');
  if (rel === 'index.html' || rel.startsWith('404')) continue;
  const href = BASE + rel.replace(/index\.html$/, '');
  if (!linked.has(href)) problems.push(`${rel}: ${href} is in no sidebar group`);
}
if (linked.size === 0) problems.push('no sidebar link on any page');

if (problems.length) {
  console.error(`check-sidebar: ${problems.length} problem(s)\n  ${problems.slice(0, 20).join('\n  ')}${problems.length > 20 ? '\n  …' : ''}`);
  process.exit(1);
}
console.log(`check-sidebar: ${files.length} pages, ${linked.size} sidebar links, no empty group`);
